import { create_teams } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
export default {
  name: "CreateGroup",
  data() {
    return {
      searchQuery: "",
      groupName: "",
      allusers: [],
      selectedUsers: [],
      loading: false,
      nameRules: [v => !!v || "Group name is required", v => v.length >= 2 || "Group name must be at least 2 characters", v => v.length <= 50 || "Group name must be less than 50 characters"]
    };
  },
  mixins: [get_all_org_users],
  computed: {
    filteredUsers() {
      if (!this.searchQuery.trim()) {
        return this.allusers;
      }
      return this.allusers.filter(user => {
        return user.full_user_name.toLowerCase().includes(this.searchQuery.toLowerCase()) || user.designation && user.designation.toLowerCase().includes(this.searchQuery.toLowerCase());
      });
    }
  },
  async mounted() {
    await this.get_all_org_users();
    this.allusers = this.orgUsers.filter(user => user.user_status === "ACTIVE");
    this.allusers = this.allusers.filter(user => user.user_email_id !== this.$store.getters.GetUserObj.user.user_email_id);
  },
  methods: {
    removeUser(index) {
      this.selectedUsers.splice(index, 1);
    },
    isUserSelected(user) {
      return this.selectedUsers.some(selectedUser => selectedUser.user_id === user.user_id);
    },
    CreatingGroup() {
      if (this.$refs.form.validate()) {
        if (this.selectedUsers.length > 0) {
          this.create_teams_message();
        } else {
          this.$emit("errorMsg", "Please select at least one member");
        }
      }
    },
    async create_teams_message() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      var users = this.selectedUsers.map(user => user.user_id);
      try {
        let result = await API.graphql(graphqlOperation(create_teams, {
          input: {
            team_name: this.groupName.trim(),
            team_description: this.groupName.trim(),
            user_id: users
          }
        }));
        var response = JSON.parse(result.data.create_teams);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.resetForm();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors?.[0]?.message || "An error occurred while creating the group");
        this.loading = false;
      }
    },
    resetForm() {
      this.groupName = "";
      this.selectedUsers = [];
      this.searchQuery = "";
      if (this.$refs.form) {
        this.$refs.form.reset();
      }
    }
  }
};
